package mail

import "strings"

// autoHeaders mark mail a machine wrote by being there at all.
var autoHeaders = []string{"list-id", "list-unsubscribe", "x-autoreply", "x-autorespond", "x-autogenerated"}

// Automatic reports mail no person wrote: auto-replies, bulk and list mail,
// bounces and delivery reports. Dropping it also ends reply loops between two
// machines. headers has lower-case names; from is the bare sender address.
func Automatic(headers map[string]string, from string) bool {
	// RFC 3834: anything but "no" is automatic ("auto-replied", "auto-generated", …).
	if v := strings.ToLower(strings.TrimSpace(headers["auto-submitted"])); v != "" && v != "no" && !strings.HasPrefix(v, "no ") && !strings.HasPrefix(v, "no;") {
		return true
	}
	switch strings.ToLower(strings.TrimSpace(headers["precedence"])) {
	case "bulk", "list", "junk", "auto_reply":
		return true
	}
	for _, name := range autoHeaders {
		if _, ok := headers[name]; ok {
			return true
		}
	}
	// Exchange: mail that asks not to be answered automatically is itself automatic.
	suppress := strings.ToLower(headers["x-auto-response-suppress"])
	for _, word := range []string{"all", "oof", "autoreply"} {
		if strings.Contains(suppress, word) {
			return true
		}
	}
	// A delivery status notification (RFC 3464) is a report, not a reply.
	if strings.HasPrefix(strings.ToLower(strings.TrimSpace(headers["content-type"])), "multipart/report") {
		return true
	}
	local, _, _ := strings.Cut(strings.ToLower(from), "@")
	return local == "mailer-daemon" || local == "postmaster"
}
